table notices: CREATE TABLE notices (user text not null, account text not null, room text not null, created integer not null, primary key (user, account))
table notifications: CREATE TABLE notifications (id integer primary key autoincrement, user text not null, room text not null, event text not null, position integer not null, actions text not null, highlight integer not null default 0, read integer not null default 0, created integer not null, unique (user, event))
table onetime: CREATE TABLE onetime (user text not null, device text not null, id text not null, key text not null, primary key (user, device, id))
table outbox: CREATE TABLE outbox (id integer primary key autoincrement, destination text not null, origin text not null default '', kind text not null, body text not null, created integer not null)
